function setupCard(){const s=state(),m=s.manager,st=s.store,stage=m.stage;if(stage==='ready')return qrCard();if(stage==='signup')return `<form class="action-card" data-form="signup">${field('signupName','name','','text','required maxlength="40" autocomplete="nickname"')}<button class="button primary">${esc(t('signupSave'))}</button><p class="card-note">${esc(t(preview?'scenario':'entrySaved'))}</p></form>`;
 if(stage==='name')return `<form class="action-card" data-form="setup" data-step="name">${field('storeName','name',st.name,'text','required maxlength="50"')}<button class="button primary">${esc(t('next'))}</button></form>`;
 if(stage==='menu')return `<div class="action-card"><p>${esc(t('menuDemoNote'))}</p><div class="inline-actions">${primary('uploadMenu','upload-menu')}${primary('useSample','sample-menu')}</div>${mediaCard('menu',true)}<p class="card-note">${esc(t('uploadLimit'))}</p></div>`;
 if(stage==='venue')return `<div class="action-card"><div class="inline-actions">${primary('uploadVenue','upload-venue')}${primary('skip','skip-venue')}</div>${mediaCard('venue',true)}${st.media.some(x=>x.kind==='venue')?primary('finishStep','next-venue'):''}<p class="card-note">${esc(t('uploadLimit'))}</p></div>`;
 if(stage==='location')return `<form class="action-card" data-form="setup" data-step="location"><div class="form-pair">${field('country','country',st.country,'text','required maxlength="40"')}${field('address','address',st.address,'text','required maxlength="200"')}</div><button class="button primary">${esc(t('next'))}</button></form>`;
 if(stage==='contact')return `<form class="action-card" data-form="setup" data-step="contact"><div class="form-pair">${field('phone','phone',st.phone,'tel','maxlength="40"')}${field('email','email',st.email,'email','maxlength="150"')}</div><button class="button primary">${esc(t('next'))}</button></form>`;
 if(stage==='sns')return `<form class="action-card" data-form="setup" data-step="sns">${field('website','website',st.website,'url','placeholder="https://…" maxlength="250"')}<button class="button primary">${esc(t('next'))}</button></form>`;
 return `<form class="action-card" data-form="setup" data-step="review"><h3>${esc(st.name)}</h3><p>${esc(st.address)}<br>${esc(st.phone)} ${esc(st.email)}<br>${esc(st.website)}</p><h4>${esc(t('menuReview'))}</h4><p class="card-note">${esc(t('menuDemoNote'))}</p>${menuFor(s).map(x=>`<fieldset class="review-menu" data-menu-id="${x.id}"><label>${esc(t('menuName'))}<input name="name-${x.id}" value="${esc(x.name[lang]||x.name.ko)}" required maxlength="100"></label><label>${esc(t('menuDescription'))}<textarea name="description-${x.id}" maxlength="500">${esc(x.description[lang]||x.description.ko||'')}</textarea></label><div class="form-pair"><label>VND<input type="number" name="price-${x.id}" value="${x.price}" min="1000" max="9999000" step="1000" required></label><label><input type="checkbox" name="available-${x.id}" ${x.available?'checked':''}>${esc(t('available'))}</label></div><button type="button" class="button" data-remove-menu="${x.id}">${esc(t('deleteMenu'))}</button></fieldset>`).join('')}<button type="button" class="button" data-action="add-menu">${icon('plus')}${esc(t('newMenu'))}</button><label class="consent"><input name="approved" type="checkbox" required><span>${esc(t('menuApproved'))}</span></label><button class="button primary">${esc(t('publish'))}</button><p class="card-note">${esc(t('reviewHelp'))}</p></form>`;}
function setupPrompt(){const stage=state().manager.stage;return {signup:'signupIntro',name:'askName',menu:'askMenu',venue:'askVenue',location:'askLocation',contact:'askContact',sns:'askSns',review:'reviewSetup',ready:'created'}[stage];}
function addSetup(){assistant(setupPrompt(),'setup');}
function sampleHomeCard(){return `<div class="action-card sample-home"><div class="sample-brand"><img src="assets/brand.png" alt="Jumo" width="64" height="64"><div><h3>${esc(state().store.name)}</h3><p>${esc(t('sampleAbout'))}</p></div></div><div class="inline-actions"><button class="button primary" data-action="dashboard">${icon('dashboard')}${esc(t('sampleDashboard'))}</button>${chip('interpreterTitle','interpreter')}${chip('sampleMenu','menu')}${chip('sampleInfo','store-info')}</div>${sample?liveConnectCard():''}</div>${briefCard()}`;}
function storeInfoCard(){const s=state().store;return `<div class="action-card"><h3>${esc(s.name)}</h3><dl class="store-info">${[['country',countryName(s.country,lang)],['address',sampleAddress(state(),lang)],['sampleHours',s.hours||'—'],['phone',s.phone||'—'],['email',s.email||'—']].map(([k,val])=>`<div><dt>${esc(t(k))}</dt><dd>${esc(val)}</dd></div>`).join('')}</dl>${s.website?`<a class="shared-link" href="${esc(s.website)}" target="_blank" rel="noopener">${esc(s.website)}</a>`:''}<p class="card-note">${esc(t(sample?'sampleNote':'reportNote'))}</p>${chip('storeQuestion','edit')}</div>${mediaCard('venue')}`;}
function menuCard(){return `<div class="action-card menu-list">${menuFor(state()).map(x=>`<article class="menu-row">${x.image?`<img src="${esc(x.image)}" alt="${esc(x.name[lang])}" width="76" height="76" loading="lazy">`:`<span class="menu-placeholder">${icon('menu')}</span>`}<div><h3>${esc(x.name[lang])}</h3><p>${esc(x.description[lang])}</p><b>${money(x.price)}</b></div>${owner?`<span class="status">${esc(t(x.available?'available':'soldOut'))}</span>`:`<button class="icon-btn menu-add" data-add="${x.id}" aria-label="${esc(x.name[lang]+' '+t('add'))}" ${x.available?'':'disabled'}>${icon('plus')}</button>`}</article>`).join('')}<p class="card-note">${esc(t('priceNote'))}</p>${owner?'':`<button class="button" data-intent="cart">${icon('bag')}${esc(t('cart'))}${cartTotal(state(),sessionId)?' · '+money(cartTotal(state(),sessionId)):''}</button>`}</div>`;}
function fulfillmentMarkup(order){
 const f=order.fulfillment;
 if(!f)return `<div class="order-location missing"><span>${icon('profile')}${esc(t('needsDetails'))}</span><small>${esc(order.table?tableLabel(order.table,lang)+' · '+t('tableUnconfirmed'):t('tableUnconfirmed'))}</small></div>`;
 if(f.channel==='dine-in')return `<div class="order-location"><span class="source-badge">${icon('menu')}${esc(t('dineIn'))}</span><strong>${esc(tableLabel(f.table,lang))}</strong></div>`;
 return `<div class="order-location delivery"><span class="source-badge">${icon('globe')}${esc(t('onlineOrder'))}</span><dl><dt>${esc(t('deliveryAddress'))}</dt><dd>${esc(f.address)}</dd><dt>${esc(t('contactPhone'))}</dt><dd><a href="tel:${esc(String(f.phone).replace(/[^+0-9]/g,''))}">${esc(f.phone)}</a></dd>${f.name?`<dt>${esc(t('recipientName'))}</dt><dd>${esc(f.name)}</dd>`:''}</dl></div>`;
}
function sourceCard(){
 const counts=channelCounts(state().orders),labels={all:'allOrders','dine-in':'dineIn',online:'onlineOrder',pending:'pendingOrders',unknown:'needsDetails'};
 return `<section class="source-overview" aria-label="${esc(t('orderSource'))}"><div class="source-heading"><h2>${esc(t('orderSource'))}</h2><span>${esc(t('sourceSummary'))}</span></div><div class="order-filters">${Object.entries(labels).filter(([key])=>key!=='unknown'||counts.unknown).map(([key,label])=>`<button data-order-filter="${key}" aria-pressed="${orderFilter===key}" class="${orderFilter===key?'active':''}">${esc(t(label))}<strong>${counts[key]}</strong></button>`).join('')}</div></section>`;
}
function beginCheckout(){if(owner||!Object.keys(v()?.cart||{}).length){toast(t('emptyCart'));return;}change(s=>{sessionOf(s,sessionId).checkoutStage='channel';});view='chat';assistant('channelQuestion','fulfillment');render(true);}
function chooseFulfillment(channel){if(owner||!['dine-in','online'].includes(channel))return;change(s=>{const visit=sessionOf(s,sessionId);visit.checkoutStage=channel;visit.checkout=visit.checkout?.channel===channel?visit.checkout:{channel,...(channel==='dine-in'?{table:table||''}:{address:'',phone:'',name:''})};});userKey(channel==='dine-in'?'dineIn':'onlineOrder');assistant(channel==='dine-in'?'tablePrompt':'deliveryPrompt','fulfillment');render(true);}
function confirmFulfillment(data){const details=attempt(()=>normalizeFulfillment(data));if(!details)return;change(s=>{const visit=sessionOf(s,sessionId);visit.checkout=details;visit.checkoutStage='review';});userKey('detailsRecorded');assistant('reviewOrder','order-review');render(true);}
function fulfillmentCard(){
 if(owner)return '';
 const stage=v()?.checkoutStage,draft=v()?.checkout||{};
 if(!stage)return `<div class="action-card"><p>${esc(t('detailsRecorded'))}</p></div>`;
 if(stage==='review')return `<div class="action-card">${fulfillmentMarkup({fulfillment:draft})}</div>`;
 if(stage==='channel')return `<div class="action-card channel-choices"><button class="button" data-channel="dine-in">${icon('menu')}<span>${esc(t('dineIn'))}</span>${icon('arrow')}</button><button class="button" data-channel="online">${icon('globe')}<span>${esc(t('onlineOrder'))}</span>${icon('arrow')}</button></div>`;
 return `<form class="action-card checkout-form" data-form="fulfillment"><input type="hidden" name="channel" value="${esc(stage)}">${stage==='dine-in'?`<label>${esc(t('tableNumber'))}<input name="table" type="number" inputmode="numeric" min="1" max="999" step="1" value="${esc(draft.table||'')}" required autocomplete="off"></label>`:`<label>${esc(t('deliveryAddress'))}<textarea name="address" rows="3" minlength="5" maxlength="300" autocomplete="street-address" required>${esc(draft.address||'')}</textarea></label><label>${esc(t('contactPhone'))}<input name="phone" type="tel" inputmode="tel" maxlength="30" autocomplete="tel" value="${esc(draft.phone||'')}" required></label><label>${esc(t('recipientName'))}<input name="name" maxlength="60" autocomplete="name" value="${esc(draft.name||'')}"></label><p class="card-note">${esc(t('detailsUse'))}</p>`}<button class="button primary" type="submit">${esc(t('confirmDetails'))}</button><button class="button" type="button" data-action="checkout-start">${esc(t('editDetails'))}</button></form>`;
}

const checkoutKeys=new Map();
function checkoutKey(quote){if(!preview){const key='modu-order-attempt:'+sessionId;let old;try{old=JSON.parse(localStorage.getItem(key));}catch{}if(old?.quote===quote)return old.id;const id=uid();localStorage.setItem(key,JSON.stringify({quote,id}));return id;}if(!checkoutKeys.has(quote))checkoutKeys.set(quote,uid());return checkoutKeys.get(quote);}
function cartCard(confirm=false){if(owner)return '';const s=state(),cart=v()?.cart||{},items=menuFor(s).filter(x=>cart[x.id]);if(!items.length)return `<div class="action-card"><p>${esc(t('emptyCart'))}</p>${chip('menuQuestion','menu')}</div>`;return `<div class="action-card"><h3>${esc(t('cart'))}</h3>${items.map(x=>`<div class="cart-row"><div><b>${esc(x.name[lang])}</b><small>${money(x.price)}</small></div><div class="quantity"><button data-quantity="${x.id}" data-delta="-1" aria-label="${esc(x.name[lang])} −">−</button><span>${cart[x.id]}</span><button data-quantity="${x.id}" data-delta="1" aria-label="${esc(x.name[lang])} +">+</button></div></div>`).join('')}<div class="card-total"><span>${esc(t('total'))}</span><strong>${money(cartTotal(s,sessionId))}</strong></div>${confirm&&v()?.checkout?`<div class="checkout-review">${fulfillmentMarkup({fulfillment:v().checkout})}</div><button class="button primary" data-action="checkout" data-quote="${esc(cartQuote(s,sessionId))}" data-fulfillment="${esc(fulfillmentKey(v().checkout))}" data-request="${checkoutKey(cartQuote(s,sessionId)+'|'+fulfillmentKey(v().checkout))}">${esc(t('confirmOrder'))}</button><button class="button" data-action="checkout-start">${esc(t('editDetails'))}</button>`:`<button class="button primary" data-action="checkout-start">${esc(t('orderInfo'))}${icon('arrow')}</button>`}<p class="card-note">${esc(t('orderNote'))}</p></div>`;}
function ordersCard(){const orders=filterOrders(state().orders.filter(o=>owner||o.sessionId===sessionId),owner?orderFilter:'all').slice().reverse();return `<div class="action-card">${orders.length?orders.map(o=>`<div class="record" data-record-id="${esc(o.id)}" tabindex="-1"><div class="record-heading"><b>#${String(o.number).padStart(3,'0')}</b><span class="status">${esc(t(o.status))}</span></div><p class="order-time">${esc(formatDateTime(o.at,lang))}</p>${fulfillmentMarkup(o)}${orderProgress(o)}${o.lines.map(l=>orderLineMarkup(o,l)).join('')}<div class="record-heading"><b>${money(o.total)}</b><span class="status">${esc(t(o.payment))}</span></div><div class="inline-actions">${owner?orderControls(o):o.payment!=='paid'?`<button class="button" data-intent="payment">${esc(t('paymentQuestion'))}</button>`:''}</div></div>`).join(''):`<p>${esc(t('emptyOrders'))}</p>`}</div>${!owner&&waitingOrder(state().orders,sessionId)?loungeMarkup(lang,{mark:botMark('greeting',true),ready:waitingOrder(state().orders,sessionId).status==='ready'}):''}`;}
function orderControls(o){const next={pending:['accepted','accept'],accepted:['preparing','prepare'],preparing:['ready','ready'],ready:['completed','serve']}[o.status];return `${next?`<button class="button" data-order="${o.id}" data-status="${next[0]}">${esc(t(next[1]))}</button>`:''}${preview&&o.payment!=='paid'?`<button class="button" data-pay="${o.id}">${esc(t('payDemo'))}</button>`:''}`;}
function reservationCard(messageId){if(state().reservations.some(r=>r.requestId===messageId))return `<small class="message-step-done">${icon('check')}${esc(t('bookingSent'))}</small>`;return `<form class="action-card" data-form="reservation" data-request="${messageId}"><div class="form-pair">${field('reservationDate','date','','date',`required min="${today()}"`)}${field('reservationTime','time','19:00','time','required')}</div><div class="form-pair">${field('partySize','partySize','2','number','min="1" max="20" required')}${field('bookingName','name',v()?.nickname||'','text','required maxlength="40"')}</div><button class="button primary">${esc(t('reserve'))}</button><p class="card-note">${esc(t('bookingNote'))}</p></form>`;}
function bookingsCard(){const rows=state().reservations.filter(r=>owner||r.sessionId===sessionId).slice().reverse();return `<div class="action-card">${rows.length?rows.map(r=>`<div class="record" data-record-id="${esc(r.id)}" tabindex="-1"><div class="record-heading"><b>${esc(formatBooking(r.date,r.time,lang))}</b><span class="status">${esc(t(r.status==='confirmed'?'bookingConfirmed':r.status==='cancelled'?'cancelBooking':'pending'))}</span></div>${bookingOrigin(r)}<p>${esc(r.name)} · ${esc(partyLabel(r.partySize,lang))}</p><div class="inline-actions">${owner&&r.status==='pending'?`<button class="button" data-booking="${r.id}" data-status="confirmed">${esc(t('bookingAccept'))}</button>`:''}${r.status!=='cancelled'?`<button class="button" data-booking="${r.id}" data-status="cancelled">${esc(t('cancelBooking'))}</button>`:''}</div></div>`).join(''):`<p>${esc(t('noBookings'))}</p>`}</div>`;}
function paymentCard(){if(!preview)return `<div class="action-card"><h3>${esc(t('paymentQuestion'))}</h3><p>${esc(t('paymentSoon'))}</p>${chip('orderQuestion','orders')}</div>`;const orders=state().orders.filter(o=>(owner||o.sessionId===sessionId)&&o.payment!=='paid');return `<div class="action-card">${orders.length?orders.map(o=>`<div class="record" data-record-id="${esc(o.id)}" tabindex="-1"><div class="record-heading"><b>#${String(o.number).padStart(3,'0')}</b><strong>${money(o.total)}</strong></div><p>${esc(t('pointsAdded'))}: ${Math.floor(o.total/1000)}P</p><button class="button primary" data-pay="${o.id}">${esc(t('payDemo'))}</button></div>`).join(''):`<p>${esc(t('noUnpaidOrders'))}</p>`}<p class="card-note">${esc(t('noRealPayment'))}</p></div>`;}
function pointsCard(){if(owner)return '';if(!preview)return `<div class="action-card"><p>${esc(t('paymentSoon'))}</p><a class="button" href="./?preview=1&lang=${lang}#games">${esc(t('localPreview'))}</a></div>`;const visit=v();return `<div class="action-card"><div class="point-balance"><span>${esc(t('pointBalance'))}</span><strong>${visit.points||0}<small>P</small></strong></div><p class="card-note">${esc(t('pointRule'))}</p><button class="button" data-action="redeem-points" ${(visit.points||0)<100?'disabled':''}>${esc(t('redeemPoints'))}</button><h4>${esc(t('couponStatus'))}</h4>${visit.coupons.length?visit.coupons.map(c=>`<div class="coupon-line"><div><b>${esc(t(c.reward))}</b><code>${esc(c.code)}</code></div><span class="status">${esc(t(c.used?'couponUsed':'couponReady'))}</span></div>`).join(''):`<p>${esc(t('noCoupon'))}</p>`}<p class="card-note">${esc(t('couponNote'))}</p>${chip('bonusTitle','games')}</div>`;}
function gamesCard(){if(owner)return '';if(!preview)return pointsCard();const visit=v(),r=visit.games.rps,w=visit.games.roulette;return `<div class="action-card bonus-card"><h3>${esc(t('bonusTitle'))}</h3><p class="card-note">${esc(t('gameNote'))}</p><h4>${esc(t('gameChoice'))}</h4><div class="hand-choices">${['rock','paper','scissors'].map(k=>`<button data-hand="${k}" ${r||gameAnimating?'disabled':''}><img src="assets/game/hand-${k}.png" alt="" width="72" height="72"><span>${esc(t(k))}</span></button>`).join('')}</div>${r?`<p class="game-feedback">${esc(t(r.capped?'rewardCap':r.outcome))} · ${esc(t('storeAssistant'))}: ${esc(t(r.opponent))}</p>`:''}<div class="roulette-inline"><div class="roulette"><div class="wheel-disc" style="transform:rotate(${w?360-(w.index*90+45):0}deg)"><img src="assets/game/reward-wheel.png" alt="${esc(t('rouletteChoice'))}" width="126" height="126">${[1,2,3,4].map(n=>`<b class="sector sector-${n}">${n}</b>`).join('')}</div><span></span></div><div><h4>${esc(t('rouletteChoice'))}</h4><button class="button" data-action="spin" ${w||gameAnimating?'disabled':''}>${esc(t(w?'alreadyPlayed':'spin'))}</button>${w?`<p class="game-feedback">${esc(t(w.capped?'rewardCap':w.reward||'noPrize'))}</p>`:''}</div></div><div class="wheel-legend">${['rewardTea','rewardSweet','rewardSnack','noPrize'].map((k,n)=>`<span><b>${n+1}</b>${esc(t(k))}</span>`).join('')}</div><p class="card-note">${esc(t('gameRules'))}</p>${chip('pointsQuestion','points')}</div>`;}
function playBonus(kind,choice){if(gameAnimating)return;const result=attempt(()=>playGame(sessionId,kind,choice));if(!result)return;gameAnimating=true;document.querySelectorAll('[data-hand],[data-action=spin]').forEach(b=>b.disabled=true);if(kind==='roulette')document.querySelectorAll('.wheel-disc').forEach(img=>img.style.transform=`rotate(${1080+360-(result.index*90+45)}deg)`);else document.querySelectorAll('.hand-choices').forEach(el=>el.classList.add('is-playing'));setTimeout(()=>{gameAnimating=false;toast(t(result.capped?'rewardCap':kind==='rps'?result.outcome:result.reward||'noPrize'));render(false);},matchMedia('(prefers-reduced-motion: reduce)').matches?0:1200);}
function qrUrl(){return new URL(`./?lang=${lang}${qrMode==='dine-in'&&table?'&table='+table:''}${cloud.storeId?'&store='+cloud.storeId:preview?'&preview=1'+(sample||sampleGuest?'&sample=owner':''):''}`,preview?location.href:CLOUD.guestBase).href;}
function qrCard(){if(owner&&qrMode==='dine-in'&&!table)table=1;if(!preview&&!cloud.published)return `<div class="action-card"><p>${esc(t('storeNotReady'))}</p>${primary('cloudRetry','cloud-retry')}</div>`;return `<div class="action-card qr-card"><div class="qr-code" data-qr="${esc(qrUrl())}"></div><div><h3>${esc(state().store.name)}</h3><div class="inline-actions"><button class="button" data-qr-mode="dine-in" aria-pressed="${qrMode==='dine-in'}">${esc(t('dineIn'))}</button><button class="button" data-qr-mode="online" aria-pressed="${qrMode==='online'}">${esc(t('onlineOrder'))}</button></div><label class="field" ${qrMode==='online'?'hidden':''}>${esc(t('tableNumber'))}<input id="qr-table" type="number" min="1" max="999" value="${table||''}"></label><p>${esc(t(preview?'localPreview':'qrGuide'))}</p>${!preview?`<p class="card-note">${esc(t('entrySaved'))}</p>`:''}<a class="shared-link" href="${esc(qrUrl())}" target="_blank" rel="noopener">${esc(qrUrl())}</a><div class="inline-actions">${primary('copyLink','copy-link')}<a class="button" href="print.html?lang=${lang}${qrMode==='online'?'&channel=online':'&table='+(table||1)}${cloud.storeId?'&store='+cloud.storeId:preview?'&preview=1'+(sample||sampleGuest?'&sample=owner':''):''}">${esc(t('printQr'))}</a><button class="button" data-action="download-qr">${esc(t('downloadQr'))}</button></div></div></div>`;}
function hydrateQr(){for(const el of document.querySelectorAll('[data-qr]')){const q=globalThis.qrcode(0,'M');q.addData(el.dataset.qr);q.make();el.innerHTML=q.createSvgTag({cellSize:4,margin:3,scalable:true});el.querySelector('svg').setAttribute('aria-label',t('qrTitle'));}}
function mediaCard(kind=null,inside=false,ids=null){const media=state().store.media.filter(m=>(!kind||m.kind===kind)&&(!ids||ids.includes(m.id)));return `<div class="${inside?'':'action-card'}">${media.length?`<div class="media-grid">${media.map(m=>`<figure>${m.type.startsWith('video/')?`<video controls preload="metadata" data-media="${m.id}"></video>`:`<img data-media="${m.id}" alt="${esc(sampleMediaName(m,lang))}">`}<figcaption>${esc(sampleMediaName(m,lang))}</figcaption></figure>`).join('')}</div>`:inside?'':`<p>${esc(t('noMedia'))}</p>`}</div>`;}
async function hydrateMedia(){objectUrls.forEach(URL.revokeObjectURL);objectUrls=[];for(const el of document.querySelectorAll('[data-media]')){try{const url=state().store.media.find(m=>m.id===el.dataset.media)?.url||await mediaUrl(el.dataset.media);if(url&&el.isConnected){if(url.startsWith('blob:'))objectUrls.push(url);el.src=url;}}catch{el.setAttribute('aria-label',t('mediaFailure'));}}}
function briefCard(){const m=metrics();return `<div class="action-card"><div class="brief-metrics">${[['summarySales',money(m.sales)],['summaryOrders',m.orders],['summaryBookings',m.bookings],['summaryRequests',m.requests]].map(([k,val])=>`<div><span>${esc(t(k))}</span><strong>${val}</strong></div>`).join('')}</div><p class="card-note">${esc(t('reportNote'))}</p><div class="inline-actions">${chip('orders','orders')}${chip('orderSource','order-sources')}${chip('reservations','bookings')}${chip('inventory','inventory')}${chip('staff','staff')}${chip('tax','tax')}</div></div>`;}
function inventoryCard(){return `<div class="action-card">${state().inventory.length?state().inventory.map(x=>sampleInventory(x,state(),lang)).map(x=>`<div class="record-line"><b>${esc(x.name)}</b><span>${x.quantity} ${esc(x.unit)}</span></div>`).join(''):`<p class="card-note">${esc(t('emptyInventory'))}</p>`}<form data-form="inventory">${field('inventoryItem','name','','text','required maxlength="60"')}<div class="form-pair">${field('quantity','quantity','0','number','required min="0" max="100000" step="0.01"')}${field('unit','unit','','text','required maxlength="15"')}</div><button class="button">${esc(t('saveItem'))}</button></form></div>`;}
function staffCard(){return `<div class="action-card">${state().staffTasks.length?state().staffTasks.map(x=>sampleTask(x,state(),lang)).map(x=>`<div class="record-line"><div><b>${esc(x.title)}</b><small>${esc(x.assignee)}</small></div>${x.done?`<span class="status">${esc(t('completed'))}</span>`:`<button class="button" data-task="${x.id}">${esc(t('done'))}</button>`}</div>`).join(''):`<p class="card-note">${esc(t('emptyTasks'))}</p>`}<form data-form="staff">${field('task','title','','text','required maxlength="120"')}${field('assignee','assignee','','text','required maxlength="40"')}<button class="button">${esc(t('saveTask'))}</button></form></div>`;}
function taxCard(){const s=state(),paid=s.orders.filter(o=>o.payment==='paid');return `<div class="action-card"><h3>${esc(t('tax'))}</h3><div class="record-line"><span>${esc(t('paidOrders'))}</span><b>${paid.length}</b></div><div class="record-line"><span>${esc(t('summarySales'))}</span><b>${money(metrics(s).sales)}</b></div>${primary('taxDownload','tax-export')}</div>`;}
function visitLocation(id){const visit=state().sessions.find(v=>v.id===id),o=state().orders.filter(o=>o.sessionId===id&&o.fulfillment).at(-1);return o?.fulfillment.channel==='online'?t('onlineOrder'):o?.fulfillment.table?tableLabel(o.fulfillment.table,lang):visit?.table?tableLabel(visit.table,lang)+' · '+t('tableUnconfirmed'):t('tableUnconfirmed');}
function dashboard(){const s=state(),attention=s.events.filter(e=>['complaint','eventStaff'].includes(e.type)&&!e.reviewed);return `<section class="manager-dashboard"><div class="dashboard-heading"><div><h1>${esc(t('liveSummary'))}</h1><p>${esc(t(sample?'sampleNote':'reportNote'))}</p></div><button class="button" data-action="chat">${icon('chat')}${esc(t('askManager'))}</button></div>${sample?liveConnectCard():liveConnectedCard()}<a class="button" href="#team">${icon('profile')}${esc(t('team'))}</a>${briefCard()}${interpreterInbox()}${sourceCard()}<div class="dashboard-columns"><section><h2>${esc(t('orders'))}</h2>${ordersCard()}<h2>${esc(t('reservations'))}</h2>${bookingsCard()}</section><section><h2>${esc(t('needsAttention'))}</h2><div class="action-card">${attention.length?attention.map(e=>`<div class="record"><b>${esc(t(e.type))}</b><small class="request-source">${esc(visitLocation(e.sessionId))}</small><p>${esc(e.detail.questionKey?t(e.detail.questionKey):e.detail.question||t('staffSent'))}</p><button class="button" data-review="${e.id}">${esc(t('resolve'))}</button></div>`).join(''):`<p>${esc(t('noActivity'))}</p>`}</div><h2>${esc(t('guestLog'))}</h2><div class="action-card">${s.sessions.length?s.sessions.slice(-8).reverse().map(visit=>`<details class="guest-log"><summary>${esc(visitLocation(visit.id))} · ${esc(LANGS[visit.lang]||visit.lang)} <span>${(visit.thread||[]).filter(x=>x.role==='user').length}</span></summary>${(visit.thread||[]).map(m=>m.interpretation?interpreterLog(m):`<p><b>${esc(m.role==='user'?t('guest'):s.store.name)}</b><br>${esc(m.text|| (m.answer?answerText(m.answer,visit.lang):(CHAT_COPY[visit.lang]?.[m.key]||UI[visit.lang]?.[m.key]||'')))}</p>`).join('')}${visit.coupons.map(c=>`<div class="coupon-line"><span>${esc(t(c.reward))}<code>${esc(c.code)}</code></span>${c.used?esc(t('couponUsed')):`<button class="button" data-coupon="${c.id}" data-visit="${visit.id}">${esc(t('redeem'))}</button>`}</div>`).join('')}</details>`).join(''):`<p>${esc(t('noRecords'))}</p>`}</div><h2>${esc(t('media'))}</h2>${mediaCard()}</section></div></section>`;}
function routeIntent(text){if(/라미 통역|통역함|통역|interpreter|phiên dịch/i.test(text))return 'interpreter';if(owner&&/어디서|온라인|테이블|배달|주문.*경로|order source|delivery|which table/i.test(text))return 'order-sources';const normalized=text.toLowerCase();const exactKeys={setup:'setup',brief:'brief',menuQuestion:'menu',orderQuestion:'cart',reservationQuestion:'reservation',paymentQuestion:'payment',pointsQuestion:'points',salesQuestion:'sales',inventoryQuestion:'inventory',staffQuestion:'staff',taxQuestion:'tax',storeQuestion:'edit',qRecommend:'recommend',qIngredients:'ingredients',qSpicy:'spicy',qStory:'story',qHours:'hours',qComplaint:'complaint',qPayment:'payment'};for(const copy of [CHAT_COPY[lang],UI[lang]])for(const [key,intent] of Object.entries(exactKeys))if(copy?.[key]&&text===copy[key])return intent;
 if(owner){if(/메뉴|menu|thực đơn|菜单|メニュー|ម៉ឺនុយ|ເມນູ|मेन्यू/.test(normalized)&&!/수정|변경|edit|update/.test(normalized))return 'menu';if(/샵 정보|주소|영업시간|store info|address|opening hours|địa chỉ|giờ mở|店铺信息|地址|営業時間|店舗情報|alamat|jam buka|पता|खुलने/.test(normalized))return 'store-info';if(/세금|세무|tax|thuế|税|pajak|कर/.test(normalized))return 'tax';if(/자재|재고|inventory|stock|kho|库存|在庫|stok|स्टॉक/.test(normalized))return 'inventory';if(/직원|업무|staff|employee|task|nhân viên|员工|スタッフ|karyawan|कर्मचारी/.test(normalized))return 'staff';if(/매출|매상|sales|revenue|doanh thu|销售|売上|penjualan|बिक्री/.test(normalized))return 'sales';if(/qr|링크|link|đường dẫn|链接|リンク/.test(normalized))return 'qr';if(/사진|영상|photo|video|ảnh|照片|写真/.test(normalized))return 'media';if(/예약|reservation|booking|đặt bàn|预订|予約|reservasi|बुकिंग/.test(normalized))return 'bookings';if(/주문|order|đơn hàng|订单|注文|pesanan|ऑर्डर/.test(normalized))return 'orders';if(/샵.*만들|가입|시작|setup|start|create|bắt đầu|创建|始め|mulai|शुरू/.test(normalized))return 'setup';if(/정보.*바|정보.*수정|edit.*store|update.*store/.test(normalized))return 'edit';if(/현황|상황|보고|report|status|tình hình|报告|状況|laporan/.test(normalized))return 'brief';return 'unknown';}
 if(unrelatedRequest(text))return 'knowledge';if(/직원.*불러|staff.*help|call.*staff|gọi.*nhân viên|叫.*服务员|スタッフ.*呼|panggil.*staf/.test(normalized))return 'staff';if(/사진|photo|venue|ảnh.*quán|店.*照片|店.*写真/.test(normalized))return 'media';if(/포인트|point|보너스|bonus|điểm|积分|ポイント|poin|अंक/.test(normalized))return 'points';if(/게임|가위바위보|룰렛|game|roulette|trò chơi|游戏|ゲーム|permainan|खेल/.test(normalized))return 'games';if(/예약|reservation|book.*table|đặt bàn|预订|予約|reservasi|बुकिंग/.test(normalized))return 'reservation';if(/내 주문|order status|my order|đơn của|我的订单|注文状況|pesanan saya/.test(normalized))return 'orders';if(/주문하고|장바구니|order food|cart|đặt món|购物车|注文したい|keranjang/.test(normalized))return 'cart';if(/메뉴.*보|menu|메뉴판|thực đơn|菜单|メニュー|मेन्यू/.test(normalized)&&!/추천|recommend|gợi ý|推荐|おすすめ/.test(normalized))return 'menu';const c=classify(text);return {replyPayment:'payment',replyIngredients:'ingredients',replyRecommend:'recommend',replySpicy:'spicy',replyStory:'story',replyHours:'hours',replyComplaint:'complaint'}[c]||'knowledge';}
async function intent(action,text){
 if(busy)return;
 interpreterMode=action==='interpreter';
 view='chat';sidebar=false;history.replaceState(null,'','#chat');if(text)user(text);
 busy=true;responding=true;render(true);
 try{
  // A short scenario transition makes the response state visible; no model is called.
  await new Promise(resolve=>setTimeout(resolve,650));
  busy=false;responding=false;answerIntent(action,text);
 }catch(error){toast(t('storageError'));}
 finally{busy=false;responding=false;if(document.querySelector('.pending-reply'))render(false);}
}
function answerIntent(action,text){if(action==='interpreter'){assistant('interpreterNote','interpreter');render(true);return;}if(owner){switch(action){case 'order-sources':orderFilter='all';assistant('sourceSummary','order-sources');break;case 'menu':assistant(null,'menu');break;case 'store-info':assistant('sampleInfo','store-info');break;case 'setup':addSetup();break;case 'edit':editStore();addSetup();break;case 'qr':if(state().manager.completed)assistant('created','qr');else addSetup();break;case 'media':assistant('uploadLocal','media');break;case 'brief':case 'sales':assistant(action==='sales'?'salesNote':'reportNote','brief');break;case 'orders':assistant('reportNote','orders');break;case 'bookings':case 'reservation':assistant('reportNote','bookings');break;case 'inventory':assistant('inventoryNote','inventory');break;case 'staff':assistant('staffNote','staff');break;case 'tax':assistant('taxNote','tax');break;default:assistant('managerUnknown','welcome');}render(true);return;}
 switch(action){case 'owner-locked':assistant('ownerLocked','owner-locked');break;case 'waiting':assistant('waitingAnswer','waiting');break;case 'wait-status':assistant(null,'orders');break;case 'wait-menu':answerIntent('ingredients');return;case 'wait-shop':answerIntent('story');return;case 'staff':addRequest(sessionId);assistant('staffSent');break;case 'media':assistant('galleryTitle','media');break;case 'menu':assistant('orderReady','menu');break;case 'cart':assistant('orderReady','cart');break;case 'orders':assistant('reportNote','orders');break;case 'reservation':assistant('reservePrompt','reservation');if(state().reservations.some(r=>r.sessionId===sessionId))assistant(null,'bookings');break;case 'payment':assistant('payPrompt','payment');break;case 'points':assistant('pointRule','points');break;case 'games':assistant('gameNote','games');break;default:{const q={recommend:'qRecommend',ingredients:'qIngredients',spicy:'qSpicy',story:'qStory',hours:'qHours',complaint:'qComplaint'}[action];const answer=resolveAnswer(text||t(q||'menuQuestion'),q,state(),lang),key=recordChat(sessionId,text||t(q||'menuQuestion'),answer.key,lang,answer.key!=='offTopic',answer.data);addMessage(role,sessionId,{role:'assistant',answer:{key,answerData:key===answer.key?answer.data:null},card:action==='recommend'&&key!=='limitReached'?'menu':null});}}
 render(true);}
async function handleFiles(files){if(busy)return;busy=true;toast(t(preview?'uploadLocal':'cloudSave'));try{if(!preview&&!cloud.active)throw Error('ownerAccess');const records=preview?await saveFiles(files,uploadKind):await cloud.upload(files,uploadKind);if(preview)addMedia(records,uploadKind);user(records.map(x=>x.name).join('\n'));assistant('uploaded','media',{ids:records.map(x=>x.id)});if(uploadKind==='menu'&&state().manager.stage==='menu'){saveSetup('menu',{});addSetup();}else if(state().manager.stage==='venue')addSetup();if(!preview)await cloud.flush();render(true);}catch(e){toast(t(e.message==='uploadLimit'?'uploadLimit':'mediaFailure'));}finally{busy=false;}}
function openFiles(kind){uploadKind=kind;const input=$('#file-input');input.accept=kind==='menu'?'image/jpeg,image/png,image/webp,image/heic,image/heif':'image/jpeg,image/png,image/webp,image/heic,image/heif,video/mp4,video/webm,video/quicktime';input.click();}
function refresh(){render(false);}
document.addEventListener('click',async e=>{const button=e.target.closest('button');if(!button||button.disabled||busy||(owner&&!ownerAuth?.ready))return;const data=button.dataset;if(data.entryLang&&!owner&&!guestEntered){lang=data.entryLang;setLang(lang);renderGuestIntro();return;}if(data.action==='guest-enter'&&!owner&&!guestEntered){guestEntered=true;await startApp();return;}if(data.script){await sendInterpretation(data.script,PHRASES[lang][data.script].request,lang);return;}if(data.interpreterReply){await sendInterpretedReply(data.visit,data.interpreterReply);return;}if(data.qrMode){qrMode=data.qrMode;render(false);return;}if(data.dismissNotice){liveNotices=liveNotices.filter(n=>n.key!==data.dismissNotice);renderLiveFeed();return;}if(data.openNotice){const notice=liveNotices.find(n=>n.key===data.openNotice);if(notice){orderFilter='all';if(owner){view='dashboard';sidebar=false;history.replaceState(null,'','#dashboard');render(false);}else{view='chat';if(notice.kind!=='interpretations')assistant(null,notice.kind==='orders'?'orders':'bookings');render(false);}document.querySelector('[data-record-id="'+CSS.escape(notice.id)+'"], [data-message="'+CSS.escape(notice.id)+'"]')?.focus({preventScroll:false});}return;}if(data.orderFilter){orderFilter=data.orderFilter;render(false);return;}if(data.channel){chooseFulfillment(data.channel);return;}if(data.intent){intent(data.intent,button.textContent.trim());return;}if(data.add){const ok=attempt(()=>updateCart(sessionId,data.add,1));if(ok){toast(t('added'));if(!currentMessages().some(m=>m.card==='cart'))assistant(null,'cart');render(false);}return;}if(data.quantity){attempt(()=>updateCart(sessionId,data.quantity,Number(data.delta)));render(false);return;}if(data.order){if(preview)attempt(()=>setOrderState(data.order,data.status));else await remote(()=>cloud.mutate('orders/'+data.order,'PATCH',{status:data.status}));refresh();return;}if(data.pay){if(!preview){toast(t('paymentSoon'));return;}const result=attempt(()=>payOrder(data.pay,owner?undefined:sessionId));if(result){if(!owner){assistant('paidReply','points');assistant('waitingInvite','waiting');}toast(t('paidReply'));render(!owner);}return;}if(data.booking){if(preview)attempt(()=>updateReservation(data.booking,data.status,owner?undefined:sessionId));else await remote(()=>cloud.mutate('reservations/'+data.booking,'PATCH',{status:data.status}));render(false);return;}if(data.task){completeTask(data.task);refresh();return;}if(data.review){if(preview)markReviewed(data.review);else await remote(()=>cloud.mutate('review/'+data.review,'PATCH',{}));refresh();return;}if(data.coupon){redeemCoupon(data.visit,data.coupon);refresh();return;}if(data.hand&&preview){playBonus('rps',data.hand);return;}if(data.removeMenu){captureMenu(document.querySelector('[data-step=review]'));change(s=>{if(s.items.length>1)s.items=s.items.filter(x=>x.id!==data.removeMenu);});render(false);return;}switch(data.action){case 'team-connect':{button.disabled=true;button.textContent=t('connecting');const id=await remote(async()=>{const id=await connectDemoShop(state());const credential=JSON.parse(localStorage.getItem('modu-owner:'+id));await importSampleTeam(credential);return id;});if(id){createDemoEntry(sessionStorage,'modu-owner-demo-entry:cloud').enter('email');location.href='owner.html?lang='+lang+'&live=1&store='+encodeURIComponent(id)+'&v=5.10.1#team';}else render(false);break;}case 'team':if(!owner)return;view='team';sidebar=false;history.replaceState(null,'','#team');render(false);window.scrollTo({top:0,behavior:'instant'});break;case 'connect-demo':{button.disabled=true;button.textContent=t('liveOpening');const demo=createOwnerSample(lang);demo.manager.messages=[];const id=await remote(()=>connectDemoShop(demo));if(id){createDemoEntry(sessionStorage,'modu-owner-demo-entry:cloud').enter('email');location.href='owner.html?lang='+lang+'&live=1&store='+encodeURIComponent(id)+'&v=5.6.0#dashboard';}else render(false);break;}case 'checkout-start':beginCheckout();break;case 'sample-reset':if(!sample)return;if(!resetConfirm){resetConfirm=true;render(false);return;}replaceState(createOwnerSample(lang));recordTracker.reset();liveNotices=[];resetConfirm=false;startAt=null;view='chat';history.replaceState(null,'','#chat');render(true);toast(t('sampleResetDone'));break;case 'sample-reset-cancel':resetConfirm=false;render(false);break;case 'security':view='security';sidebar=false;history.replaceState(null,'','#security');render(false);window.scrollTo({top:0,behavior:'instant'});break;case 'demo-logout':if(!owner||!await remote(async()=>{await cloud.flush();return true;}))return;await ownerAuth.logout();break;case 'cloud-retry':await remote(async()=>{await cloud.flush();await cloud.refresh(true);});render(false);break;case 'add-menu':captureMenu(document.querySelector('[data-step=review]'));change(s=>{s.items.push({id:'custom-'+uid(),name:Object.fromEntries(Object.keys(LANGS).map(l=>[l,t('newMenu')])),description:Object.fromEntries(Object.keys(LANGS).map(l=>[l,''])),price:10000,available:true,image:'',category:'custom'});});render(false);break;case 'sidebar':sidebar=!sidebar;render(false);break;case 'chat':view='chat';sidebar=false;history.replaceState(null,'','#chat');render(false);break;case 'dashboard':view=view==='dashboard'?'chat':'dashboard';sidebar=false;history.replaceState(null,'','#'+view);render(false);window.scrollTo({top:0,behavior:'instant'});break;case 'new':view='chat';sidebar=false;startAt=thread(role,sessionId).at(-1)?.id||null;history.replaceState(null,'','#chat');render(false);break;case 'cart':intent('cart',t('cart'));break;case 'attach':openFiles(state().manager.stage==='menu'?'menu':'venue');break;case 'upload-menu':openFiles('menu');break;case 'upload-venue':openFiles('venue');break;case 'sample-menu':saveSetup('menu',{});userKey('useSample');addSetup();render(true);break;case 'skip-venue':case 'next-venue':saveSetup('venue',{});userKey(data.action==='skip-venue'?'skip':'finishStep');addSetup();render(true);break;case 'checkout':{const details=attempt(()=>normalizeFulfillment(JSON.parse(data.fulfillment||'null')));if(!details)return;const result=preview?attempt(()=>placeOrder(sessionId,data.request,data.quote,details)):await remote(()=>cloud.order(data.request,data.quote,details,lang));if(result){change(s=>{const visit=sessionOf(s,sessionId);visit.checkout=null;visit.checkoutStage=null;});checkoutKeys.clear();if(!preview)localStorage.removeItem('modu-order-attempt:'+sessionId);assistant('orderSent','orders');render(true);}else refresh();break;}case 'redeem-points':{const result=attempt(()=>redeemPoints(sessionId));if(result){assistant('redeemed','points');render(true);}break;}case 'spin':if(preview)playBonus('roulette');break;case 'copy-link':try{await navigator.clipboard.writeText(qrUrl());toast(t('copied'));}catch{toast(t('copyFailed'));}break;case 'download-qr':{const q=qrcode(0,'M');q.addData(qrUrl());q.make();download('modu-ai-qr.svg',q.createSvgTag({cellSize:6,margin:4,scalable:true}),'image/svg+xml');break;}case 'tax-export':download('modu-ai-demo-payment-records.csv',taxCsv(),'text/csv;charset=utf-8');break;}});
document.addEventListener('submit',async e=>{e.preventDefault();if(owner&&!ownerAuth?.ready)return;const form=e.target,data=Object.fromEntries(new FormData(form));if(busy)return;if(form.id==='chat-form'){const text=data.message?.trim();if(!text)return;if(!owner&&v()?.checkoutStage==='dine-in'){const found=text.match(/(?:^|\D)([1-9][0-9]{0,2})(?:\D|$)/);if(found){confirmFulfillment({channel:'dine-in',table:found[1]});return;}}if(!owner&&v()?.checkoutStage==='online'){user(text);assistant('deliveryPrompt','fulfillment');render(true);return;}if(owner&&['name','signup'].includes(state().manager.stage)&&currentMessages().some(m=>m.card==='setup')){if(state().manager.stage==='signup'){if(!attempt(()=>ownerSignup(text)))return;}else saveSetup('name',{name:text});user(text);addSetup();render(true);return;}if(!owner){const loungeIntent=waitingIntent(text);if(loungeIntent){intent(loungeIntent,text);return;}const matched=matchRequest(text,lang);if(matched){await sendInterpretation(matched.scenarioId,text,matched.lang);return;}if(interpreterMode){user(text);assistant('interpreterUnsupported','interpreter');render(true);return;}}intent(routeIntent(text),text);return;}switch(form.dataset.form){case 'fulfillment':confirmFulfillment(data);break;case 'signup':if(attempt(()=>ownerSignup(data.name))){user(data.name);addSetup();render(true);}break;case 'setup':{const step=form.dataset.step;const result=attempt(()=>{if(step==='review'){if(!data.approved)throw new Error('approvalRequired');captureMenu(form);}return saveSetup(step,data);});if(result){if(!preview&&!await remote(async()=>{await cloud.flush();return true;})){render(false);return;}step==='review'?userKey('menuApproved'):user(Object.values(data).filter(x=>x&&x!=='on').join(' · '));addSetup();render(true);}break;}case 'reservation':{const r=preview?attempt(()=>reserve(sessionId,data,form.dataset.request)):await remote(()=>cloud.mutate('reservations','POST',{...data,lang,requestId:form.dataset.request}));if(r){user(`${formatBooking(data.date,data.time,lang)} · ${partyLabel(data.partySize,lang)} · ${data.name}`);assistant('bookingSent','bookings');render(true);}break;}case 'inventory':if(attempt(()=>saveInventory(data))){user(`${data.name} · ${data.quantity} ${data.unit}`);assistant('savedItem','inventory');render(true);}break;case 'staff':if(attempt(()=>saveTask(data))){user(`${data.assignee} · ${data.title}`);assistant('taskSaved','staff');render(true);}break;}});
document.addEventListener('change',e=>{if(e.target.id==='qr-table'){table=Math.max(1,Math.min(999,Number(e.target.value)||1));render(false);}if(e.target.id==='language'){lang=e.target.value;setLang(lang);if(!owner&&sessionId)change(s=>{sessionOf(s,sessionId).lang=lang;});render(false);}if(e.target.id==='file-input')handleFiles([...e.target.files]);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&sidebar){sidebar=false;render(false);$('.chat-topbar [data-action=sidebar]')?.focus();}if(e.target.id==='message-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#chat-form').requestSubmit();}});
document.addEventListener('input',e=>{if(e.target.id==='message-input'){e.target.style.height='auto';e.target.style.height=Math.min(e.target.scrollHeight,160)+'px';}});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY&&preview)liveRefresh();});
document.addEventListener('compositionstart',()=>composing=true);
document.addEventListener('compositionend',()=>{composing=false;if(deferredRefresh)liveRefresh();});
window.addEventListener('hashchange',()=>{if(['#dashboard','#team','#security'].includes(location.hash)&&owner){view=location.hash.slice(1);render(false);window.scrollTo({top:0,behavior:'instant'});}});
matchMedia('(max-width:760px)').addEventListener('change',()=>render(false));
function captureMenu(form){if(!form)return;const data=Object.fromEntries(new FormData(form));change(s=>{s.items=menuFor(s).map(item=>{const name=String(data['name-'+item.id]||item.name[lang]),description=String(data['description-'+item.id]||'');return {...item,name:name===item.name[lang]?item.name:Object.fromEntries(Object.keys(LANGS).map(l=>[l,name])),description:description===item.description[lang]?item.description:Object.fromEntries(Object.keys(LANGS).map(l=>[l,description])),price:Number(data['price-'+item.id]),available:!!data['available-'+item.id]};});s.menu={};});}
cloud.onchange=changed=>{const status=document.querySelector('[data-cloud-status]');if(status)status.textContent=t(cloud.status);if(changed&&cloud.loaded)liveRefresh();};
cloud.onerror=e=>{if(owner&&e.message==='ownerAccess'){ownerAuth.lock();}else toast(t(e.message in CHAT_COPY[lang]?e.message:'cloudError'));};

function liveConnectCard(){return `<div class="live-connect"><div>${botMark('greeting')}<div><h3>${esc(t('liveConnect'))}</h3><p>${esc(t('liveConnectNote'))}</p></div></div><button class="button primary" data-action="connect-demo">${esc(t('liveConnect'))}${icon('arrow')}</button></div>`;}
function liveConnectedCard(){return cloud.active?`<div class="live-connect connected"><div>${botMark('order')}<div><h3>${esc(t('liveLinked'))}</h3><p>${esc(t('liveLinkedNote'))}</p></div></div><button class="button" data-intent="qr">${icon('qr')}${esc(t('guestLink'))}</button></div>`:'';}
function orderProgress(o){const current=ORDER_STEPS.indexOf(o.status);return `<ol class="order-progress" aria-label="${esc(t('orderProgress'))}">${ORDER_STEPS.map((status,i)=>`<li class="${i<=current?'reached':''} ${i===current?'current':''}" ${i===current?'aria-current="step"':''}><i aria-hidden="true">${i<current?'✓':i+1}</i><span>${esc(t(status))}</span></li>`).join('')}</ol>`;}
function bookingOrigin(r){return `<div class="booking-origin">${icon(r.table?'menu':'globe')}<strong>${esc(r.table?tableLabel(r.table,lang):t('onlineBooking'))}</strong>${r.table?`<small>${esc(t('tableOrigin'))}</small>`:''}</div>`;}
function syncNotices(){for(const n of recordTracker.scan(state())){liveNotices=liveNotices.filter(old=>old.key!==n.key);liveNotices.unshift(n);}liveNotices=liveNotices.slice(0,8);}
function renderLiveFeed(){
 let host=document.querySelector('#live-record-feed');
 if(!host){host=document.createElement('aside');host.id='live-record-feed';host.setAttribute('aria-label',t('liveFeed'));host.setAttribute('aria-live','polite');host.setAttribute('aria-atomic','true');document.body.append(host);}
 const n=liveNotices[0];if(n?.kind==='interpretations'){renderInterpreterNotice(host,n);return;}const row=n&&state()[n.kind]?.find(r=>r.id===n.id);
 const html=row?`<div class="live-alert">${botMark('order',true)}<div class="live-alert-body"><small>${esc(t('liveFeed'))}${liveNotices.length>1?' · '+liveNotices.length:''}</small><h2>${esc(t(n.type==='new'?(n.kind==='orders'?'newOrderAlert':'newBookingAlert'):(n.kind==='orders'?'orderUpdated':'bookingUpdated')))}</h2>${n.kind==='orders'?`<p class="live-alert-status">#${String(row.number).padStart(3,'0')} · ${esc(t(row.status))}</p>${fulfillmentMarkup(row)}`:`<p>${esc(formatBooking(row.date,row.time,lang))} · ${esc(row.name)} · ${esc(partyLabel(row.partySize,lang))}</p>${bookingOrigin(row)}<p>${esc(t(row.status==='confirmed'?'bookingConfirmed':row.status==='cancelled'?'cancelBooking':'pending'))}</p>`}<button class="button" data-open-notice="${esc(n.key)}">${esc(t('openRecord'))}${icon('arrow')}</button></div><button class="icon-btn alert-dismiss" data-dismiss-notice="${esc(n.key)}" aria-label="${esc(t('dismissAlert'))}">${icon('close')}</button></div>`:'';
 if(host.dataset.signature!==html){host.innerHTML=html;host.dataset.signature=html;}
 host.hidden=!row;
}
// Snapshot changes must not erase a draft or move the cursor while someone types.
function liveRefresh(){
 if(view==='team'&&owner){const form=document.querySelector('[data-team-register]'),editing=form?.contains(document.activeElement),draft=editing?Object.fromEntries(new FormData(form)):null,permissions=editing?new FormData(form).getAll('permission'):[],y=scrollY;render(false);if(draft){const next=document.querySelector('[data-team-register]');if(next){next.elements.name.value=draft.name;next.elements.role.value=draft.role;next.querySelectorAll('[name=permission]').forEach(x=>x.checked=permissions.includes(x.value));}}window.scrollTo({top:y,behavior:'instant'});return;}

 syncNotices();if(owner&&!entry.current)return;renderLiveFeed();
 if(busy||composing){deferredRefresh=true;return;}deferredRefresh=false;
 const controls=[...root.querySelectorAll('input:not([type=file]),textarea,select')];
 const identify=el=>[el.id,el.name,el.form?.id,el.form?.dataset.form,el.form?.dataset.request,el.form?.dataset.step].join('|');
 const drafts=controls.map(el=>({key:identify(el),value:el.value,checked:el.checked,active:el===document.activeElement,start:el.selectionStart,end:el.selectionEnd,height:el.style.height}));
 const opened=[...root.querySelectorAll('details')].map(el=>el.open),y=scrollY;
 render(false);
 const updated=[...root.querySelectorAll('input:not([type=file]),textarea,select')];
 for(const draft of drafts){const el=updated.find(node=>identify(node)===draft.key);if(!el)continue;el.value=draft.value;if('checked' in el)el.checked=draft.checked;el.style.height=draft.height;if(draft.active){el.focus({preventScroll:true});if(typeof draft.start==='number'&&el.setSelectionRange)try{el.setSelectionRange(draft.start,draft.end);}catch{}}}
 root.querySelectorAll('details').forEach((el,i)=>el.open=opened[i]||false);window.scrollTo({top:y,behavior:'instant'});
}

async function startApp(){
 if(owner&&!ownerAuth?.ready){ownerAuth?.render();return;}
 if(!owner&&!guestEntered){renderGuestIntro();return;}
 if(!owner&&preview&&!sessionId)sessionId=ensureSession(table,lang);
 if(owner&&!entry.current){render();return;}
 if(sample&&readState().sampleVersion!==SAMPLE_VERSION)replaceState(createOwnerSample(lang));
 if(sample&&!readState().sampleRoutingVersion)replaceState(upgradeOwnerSample(readState()));
 if((sample||sampleGuest)&&!readState().interpreterSampleVersion)change(addInterpreterSample);
 if(!preview){root.innerHTML=`<main class="cloud-loading">${brandLogo()}<h1>원샵 · one shop ai</h1><p>${esc(t('cloudLoading'))}</p></main>`;try{cloud.suspended=false;if(!initialized){sessionId=await cloud.init(role,table,lang);initialized=true;}else if(cloud.active){await cloud.refresh(true);cloud.connect();}}catch(e){if(owner&&e.message==='ownerAccess'){ownerAuth.lock();return;}root.innerHTML=`<main class="cloud-loading">${brandLogo()}<h1>one shop ai</h1><p>${esc(t(e.message in CHAT_COPY[lang]?e.message:'cloudError'))}</p><button class="button" onclick="location.reload()">${esc(t('cloudRetry'))}</button></main>`;return;}}
 render();
 const initial={waiting:'waiting',interpreter:'interpreter',menu:'menu',games:'games',orders:'orders',profile:'points',orderInbox:'orders',guestLog:'brief',storeSetup:'setup',connections:'tax'}[location.hash.slice(1)];if(initial)intent(initial);
}
function suspendOwner(){cloud.pause();teamConnection?.stop();teamConnection=null;disposeTeam();}
function clearOwnerView(){suspendOwner();initialized=false;cloud.loaded=false;cloud.credential=null;cloud.dirty=false;cloud.sent.clear();cloud.remoteSignature=null;liveNotices=[];recordTracker.reset();startAt=null;sidebar=false;for(const url of objectUrls)URL.revokeObjectURL(url);objectUrls=[];document.querySelector('#live-record-feed')?.remove();root.innerHTML='';}
if(owner){ownerAuth=createOwnerAuth({root,getLang:()=>lang,onSuspend:suspendOwner,onLocked:clearOwnerView,onReady:async credential=>{cloud.useOwner(credential);cloud.suspended=false;initialized=false;await startApp();}});await ownerAuth.boot();}else await startApp();
